mapper.select:
SELECT 

WHERE p.status = 'PUBLISHED'
  AND p.plan_type = #{planType}

  AND p.partner_code = #{partnerCode}

ORDER BY COALESCE(v.monthly_price, v.charge_price), p.id

SELECT 

WHERE p.id = #{id}
  AND p.status IN ('PUBLISHED', 'ENDED')

SELECT 

WHERE p.status = 'PUBLISHED'
  AND p.plan_type = 'POSTPAID'
  AND p.id <> #{excludeId}
  AND v.network = #{network}


  AND v.data_gb IS NULL
  ORDER BY v.monthly_price, p.id


  AND v.data_gb BETWEEN #{dataGb} * 0.5 AND #{dataGb} * 1.5
  ORDER BY ABS(v.data_gb - #{dataGb}), v.monthly_price, p.id


LIMIT #{limit}

SELECT count(*)

WHERE p.status = 'PUBLISHED'
  AND p.plan_type = #{planType}

SELECT p.id, p.partner_code, p.plan_type, p.status, p.activation_url, p.published_version_id
FROM plan p
WHERE p.id = #{id}
